import {personalBoard,bindPersonalBoard} from './personal-board.js';
import {safe,keyword} from './experience.js';
export const author={name:'Lucas Egydio',handle:'lucasegydio',photo:null};
const instagram='<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="5" fill="none" stroke="currentColor" stroke-width="1.7"/><circle cx="12" cy="12" r="4" fill="none" stroke="currentColor" stroke-width="1.7"/><circle cx="17.5" cy="6.5" r="1" fill="currentColor"/></svg>';
const twitter='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 3h5l11 18h-5L4 3Zm0 18L20 3" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"/></svg>';
export const socials=()=>`<nav class="social-links" aria-label="Redes de Lucas Egydio"><a href="https://www.instagram.com/lucasegydio/" target="_blank" rel="noopener noreferrer" aria-label="Instagram de Lucas Egydio">${instagram}<span>Instagram</span></a><a href="https://x.com/lucasegydio" target="_blank" rel="noopener noreferrer" aria-label="Twitter / X de Lucas Egydio">${twitter}<span>Twitter / X</span></a></nav>`;
export const avatar=()=>author.photo?`<img class="author-avatar" src="${safe(author.photo)}" alt="Lucas Egydio">`:'<span class="author-avatar author-monogram" aria-hidden="true">LE</span>';
export function reviewByline(a){const original=a.reviewOriginal,sourceMonth=original?.source?.match(/\/(\d{4})\/(\d{2})\//),date=original?.publishedAt||(sourceMonth?sourceMonth[1]+'-'+sourceMonth[2]:String(original?.publicationYear||''));const label=/^\d{4}-\d{2}$/.test(date)?new Date(date+'-01T12:00:00Z').toLocaleDateString('pt-BR',{month:'long',year:'numeric',timeZone:'UTC'}):/^\d{4}-\d{2}-\d{2}$/.test(date)?new Date(date+'T12:00:00Z').toLocaleDateString('pt-BR',{timeZone:'UTC'}):date;return `<header class="review-byline"><div><span class="eyebrow">REVIEW</span>${original&&date?`<time datetime="${safe(date)}">${safe(label)}</time>`:'<span class="byline-demo">Texto demonstrativo</span>'}</div><a href="#sobre" class="byline-author">${avatar()}<span>${original?'Lucas Egydio':'meeting.points'}<small>${original?'Crítica e curadoria musical':'Editorial de demonstração'}</small></span></a></header>`;}
export function editorialCard(a){return `<a class="text-card editorial-note" href="#texto/escutar"><div class="editorial-image"><img class="article-image" src="${safe(a.cover)}" alt="Capa de ${safe(a.title)}" width="600" height="600" loading="lazy"></div><div class="editorial-note-copy"><span class="eyebrow">CADERNO DE ESCUTA</span><h3>O que muda quando você ouve de novo?</h3><p>Um disco, várias escutas. Detalhes que passam despercebidos na primeira vez.</p><span class="small">Texto de exemplo · 2 min <span aria-hidden="true">↗</span></span></div></a>`;}
export function editorialPage(a){return `<section class="editorial-heading"><span class="eyebrow">TEXTOS / MEETING.POINTS</span><h1>À margem<br><em>do som.</em></h1><p>Opinião, referências e conversas que começam com um disco.</p></section><section class="editorial-list">${editorialCard(a)}</section>`;}
export function aboutPage(albums){return personalBoard(albums);}
let dispose=()=>{};
export function bindEditorial(root){
 dispose();bindPersonalBoard(root);const heroArtist=root.querySelector('.hero .artist');if(heroArtist){const text=heroArtist.textContent.split('/')[0].trim(),year=heroArtist.querySelector('.small')?.textContent.replace('/','').trim();heroArtist.innerHTML=keyword(text,'person')+(year?' <span class="small">/ '+keyword(year,'year')+'</span>':'');}document.querySelector('.footer-socials').innerHTML=socials();
 const gallery=root.querySelector('.stack-gallery'),title=gallery?.querySelector('.stack-title-link strong');
 const fit=()=>{if(!title)return;const len=title.textContent.length;title.style.setProperty('--title-scale',len>45?'.64':len>28?'.78':'1');};fit();
 const observer=title?new MutationObserver(fit):null;observer?.observe(title,{childList:true,characterData:true,subtree:true});
 dispose=()=>observer?.disconnect();
}
